<dialog x-ref="trafficDialog" class="traffic-dialog" @cancel.prevent="closeTraffic()" @click="if($event.target===$refs.trafficDialog)closeTraffic()" aria-labelledby="traffic-title">
    <header class="modal-header"><div><p class="eyebrow" x-text="trafficTarget?.kind==='ports'?'PORT PON':'ONU'"></p><h2 id="traffic-title" x-text="'Traffic · '+(trafficTarget?.name||'')"></h2></div><button class="icon-button" aria-label="Tutup traffic" @click="closeTraffic()"><i data-lucide="x"></i></button></header>
    <div class="traffic-body" :class="{'is-loading':trafficBusy&&!trafficData}" :aria-busy="trafficBusy">
        @include('partials.skeleton',['show'=>'trafficBusy&&!trafficData','variant'=>'chart'])
        <div class="traffic-presets" aria-label="Rentang traffic"><template x-for="preset in trafficPresets" :key="preset[0]"><button class="btn secondary" :class="{'traffic-active':trafficRange===preset[0]}" :aria-pressed="trafficRange===preset[0]" @click="setTrafficRange(preset[0])" x-text="preset[1]"></button></template></div>
        <form class="traffic-filters" @submit.prevent="applyTrafficDates()"><label>Filter<select aria-label="Filter" x-model="trafficDateMode" @change="trafficFrom='';trafficTo=''"><option value="date">Rentang tanggal</option><option value="month">Rentang bulan</option></select></label><label>Dari (WIB)<input :type="trafficDateMode" x-model="trafficFrom" required></label><label>Sampai (WIB)<input :type="trafficDateMode" x-model="trafficTo" required></label><button class="btn primary" type="submit">Terapkan</button></form>
        <div class="traffic-meta"><span x-text="trafficData?.last_recorded_at?'Sampel terakhir: '+dateTime(trafficData.last_recorded_at)+' · '+(trafficData.source||'').toUpperCase():'Belum ada sampel'"></span><span x-show="trafficBusy">Membaca…</span><button class="btn secondary" x-show="trafficRange==='live'" @click="toggleTrafficPause()" x-text="trafficPaused?'Lanjutkan live':'Jeda live'"></button><button class="btn secondary" x-show="trafficRange!=='live'" @click="loadTraffic(false)">Refresh histori</button></div>
        <p class="onu-detail-error" role="alert" x-show="trafficError" x-text="trafficError"></p>
        <div class="traffic-summary"><template x-for="direction in ['rx','tx']" :key="direction"><section>
            <h3 class="traffic-series-label"><span class="traffic-series-line" :class="{'upload':direction==='tx'}" aria-hidden="true"></span><span x-text="direction==='rx'?'Download':'Upload'"></span></h3>
            <div class="traffic-headline"><strong x-text="trafficUnit(trafficData?.statistics[direction].current)"></strong><span x-text="trafficByteRate(trafficData?.statistics[direction].current)"></span></div>
            <dl class="traffic-extremes"><div><dt>Tertinggi</dt><dd x-text="trafficUnit(trafficData?.statistics[direction].peak)"></dd></div><div><dt>Rata-rata</dt><dd x-text="trafficUnit(trafficData?.statistics[direction].average)"></dd></div><div><dt>Terendah</dt><dd x-text="trafficUnit(trafficData?.statistics[direction].minimum)"></dd></div></dl>
        </section></template></div>
        <div class="traffic-toolbar" role="toolbar" aria-label="Kontrol grafik traffic">
            <button class="icon-button" aria-label="Zoom in" title="Zoom in" @click="trafficChartAction('in')"><i data-lucide="plus"></i></button>
            <button class="icon-button" aria-label="Zoom out" title="Zoom out" @click="trafficChartAction('out')"><i data-lucide="minus"></i></button>
            <button class="icon-button" aria-label="Zoom selection" title="Pilih rentang dengan menyeret" :aria-pressed="trafficChartMode==='select'" @click="trafficChartAction('select')"><i data-lucide="scan-search"></i></button>
            <button class="icon-button" aria-label="Pan" title="Geser grafik" :aria-pressed="trafficChartMode==='pan'" @click="trafficChartAction('pan')"><i data-lucide="move"></i></button>
            <button class="icon-button" aria-label="Reset zoom" title="Reset zoom" @click="trafficChartAction('reset')"><i data-lucide="rotate-ccw"></i></button>
            <div class="traffic-export"><button class="icon-button" aria-label="Download grafik" :aria-expanded="trafficDownloadMenu" @click="trafficDownloadMenu=!trafficDownloadMenu"><i data-lucide="menu"></i></button><div x-show="trafficDownloadMenu" @click.outside="trafficDownloadMenu=false"><button @click="downloadTraffic('png')">Download PNG</button><button @click="downloadTraffic('csv')">Download CSV</button></div></div>
        </div>
        <div class="traffic-canvas-wrap" :class="{'is-panning':trafficChartMode==='pan'}"><canvas x-ref="trafficCanvas" role="img" aria-label="Grafik traffic: Download biru solid, Upload abu-abu putus-putus. Gunakan pemilih sampel untuk membaca nilainya."></canvas></div>
        <p x-show="!trafficData?.sample_count" class="muted">Belum ada sampel pada rentang ini. Histori mulai terisi setelah pengambilan traffic aktif.</p>
        <p class="traffic-caption" x-text="trafficCaption()"></p>
        <label class="traffic-scrubber" x-show="trafficData?.points.length">Pilih titik waktu<input type="range" min="0" :max="Math.max(0,(trafficData?.points.length||1)-1)" step="1" x-model.number="trafficHover" @input="trafficFocusPoint()" aria-label="Pilih sampel traffic"></label>
        <p class="traffic-tooltip" x-show="trafficData?.points.length"><span x-text="trafficPoint().recorded_at?dateTime(trafficPoint().recorded_at):''"></span> &middot; Download <span x-text="trafficUnit(trafficPoint().rx_bps)"></span> &middot; Upload <span x-text="trafficUnit(trafficPoint().tx_bps)"></span></p>
        <div class="traffic-volume" x-show="trafficData?.volume_supported!==false"><template x-for="direction in ['rx','tx']" :key="direction"><p><span x-text="direction==='rx'?'Volume download':'Volume upload'"></span><strong x-text="trafficUnit(trafficData?.statistics[direction].volume_bytes,true)"></strong><small x-text="'Durasi terukur '+Math.round((trafficData?.statistics[direction].covered_seconds||0)/60)+' menit'"></small></p></template></div>
        <p class="small muted" x-show="trafficData?.volume_supported===false" x-text="trafficData?.volume_note||'Volume belum tersedia untuk perangkat ini.'"></p>
        <p class="small muted" x-show="trafficData?.volume_supported!==false">Volume hanya mencakup interval terukur. Jeda lebih dari 10 menit tidak dijembatani. Ekspor CSV berisi titik grafik yang diringkas sesuai rentang; statistik memakai seluruh sampel.</p>
    </div>
</dialog>
